with gaps as (select *, case when lag(event_time) over (partition by session_id order by event_time, id) is null or event_time > lag(event_time) over (partition by session_id order by event_time, id) + interval '30' day then 1 else 0 end as is_new_burst from web_events), sessions_web_events as (select *, sum(is_new_burst) over (partition by session_id order by event_time, id rows between unbounded preceding and current row) as island_id from gaps) select id, event_type, event_time, case when event_type rlike '^(click|page_view)$' then 'GROUP_B' else 'PRIORITY' end as event_type_zone from sessions_web_events order by id desc nulls last, event_type_zone desc;
